2	-- 20260420000004_bubs_grants.sql
3	-- ----------------------------------------------------------------------------
4	-- Grant table-level permissions so PostgREST (Supabase's REST API)
5	-- can actually return rows to anon and authenticated roles.
6	--
7	-- Supabase RLS policies only *filter* rows — they don't grant the
8	-- underlying SELECT permission. Every public-facing table needs
9	-- both a GRANT and at least one policy.
10	--
11	-- Without this file, every REST call returns "permission denied".
12	-- ============================================================================
13	
14	-- ── World-readable tables (public pricing, app catalog, changelog) ─────────
15	GRANT SELECT ON apps                        TO anon, authenticated;
16	GRANT SELECT ON plans                       TO anon, authenticated;
17	GRANT SELECT ON rankora_changelog           TO anon, authenticated;
18	GRANT SELECT ON rankora_feature_requests    TO anon, authenticated;
19	GRANT SELECT ON rankora_career_pages        TO anon, authenticated;  -- published only via RLS
20	GRANT SELECT ON rankora_feature_flags       TO anon, authenticated;  -- global defaults only via RLS
21	
22	-- Logged-in users can create feature requests + vote
23	GRANT INSERT, UPDATE ON rankora_feature_requests TO authenticated;
24	GRANT SELECT, INSERT, DELETE ON rankora_feature_request_votes TO authenticated;
25	
26	-- ── Authenticated-only tables (account-scoped via RLS) ─────────────────────
27	-- Every account-scoped table needs SELECT/INSERT/UPDATE/DELETE for
28	-- authenticated role. RLS policies then filter by account membership.
29	
30	GRANT SELECT, INSERT, UPDATE, DELETE ON users                        TO authenticated;
31	GRANT SELECT, INSERT, UPDATE, DELETE ON accounts                     TO authenticated;
32	GRANT SELECT, INSERT, UPDATE, DELETE ON account_users                TO authenticated;
33	GRANT SELECT                          ON account_app_access          TO authenticated;
34	GRANT SELECT                          ON subscriptions               TO authenticated;
35	GRANT SELECT                          ON usage_logs                  TO authenticated;
36	GRANT SELECT                          ON audit_logs                  TO authenticated;
37	
38	GRANT SELECT, INSERT, UPDATE, DELETE ON rankora_jobs                 TO authenticated;
39	GRANT SELECT, INSERT, UPDATE, DELETE ON rankora_resumes              TO authenticated;
40	GRANT SELECT,         UPDATE         ON rankora_results              TO authenticated;
41	GRANT SELECT,         UPDATE         ON rankora_applications         TO authenticated;
42	GRANT SELECT, INSERT, UPDATE, DELETE ON rankora_career_pages         TO authenticated;
43	GRANT SELECT, INSERT, UPDATE, DELETE ON rankora_tasks                TO authenticated;
44	GRANT SELECT, INSERT, UPDATE, DELETE ON rankora_candidate_notes      TO authenticated;
45	GRANT SELECT, INSERT,         DELETE ON rankora_candidate_tags       TO authenticated;
46	GRANT SELECT, INSERT, UPDATE, DELETE ON rankora_pipeline_stages      TO authenticated;
47	GRANT SELECT,         UPDATE         ON rankora_platform_config      TO authenticated;
48	GRANT SELECT, INSERT, UPDATE, DELETE ON rankora_api_keys             TO authenticated;
49	GRANT SELECT, INSERT, UPDATE, DELETE ON rankora_feature_flags        TO authenticated;
50	
51	-- ── Service role: full access (bypasses RLS entirely) ─────────────────────
52	-- Edge functions running with SUPABASE_SERVICE_ROLE_KEY bypass RLS
53	-- by default, but we still grant table access explicitly for clarity.
54	GRANT ALL ON ALL TABLES IN SCHEMA public TO service_role;
55	GRANT ALL ON ALL SEQUENCES IN SCHEMA public TO service_role;
56	GRANT ALL ON ALL FUNCTIONS IN SCHEMA public TO service_role;
57	
58	-- Ensure future tables (from later migrations) automatically inherit
59	-- sensible defaults without needing to re-run GRANT for each new table
60	ALTER DEFAULT PRIVILEGES IN SCHEMA public
61	  GRANT SELECT ON TABLES TO anon;
62	ALTER DEFAULT PRIVILEGES IN SCHEMA public
63	  GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO authenticated;
64	ALTER DEFAULT PRIVILEGES IN SCHEMA public
65	  GRANT ALL ON TABLES TO service_role;
