3	import { useEffect, useState } from "react";
4	import { useQuery, useQueryClient } from "@tanstack/react-query";
5	import { supabase } from "@/integrations/supabase/client";
6	
7	interface FeatureFlag {
8	  id: string;
9	  key: string;
10	  name: string;
11	  description: string;
12	  enabled: boolean;
13	  value_json: Record<string, unknown> | null;
14	}
15	
16	/**
17	 * Hook to read all feature flags with real-time updates.
18	 * Returns a map of flag key → { enabled, value_json }.
19	 */
20	export function useFeatureFlags() {
21	  const qc = useQueryClient();
22	
23	  const { data: flags, isLoading } = useQuery({
24	    queryKey: ["feature_flags"],
25	    queryFn: async () => {
26	      const { data, error } = await supabase
27	        .from("feature_flags")
28	        .select("*")
29	        .order("key");
30	      if (error) throw error;
31	      return data as unknown as FeatureFlag[];
32	    },
33	    staleTime: 60_000,
34	  });
35	
36	  useEffect(() => {
37	    const channel = supabase
38	      .channel("feature_flags_realtime")
39	      .on(
40	        "postgres_changes",
41	        { event: "*", schema: "public", table: "feature_flags" },
42	        () => {
43	          qc.invalidateQueries({ queryKey: ["feature_flags"] });
44	        }
45	      )
46	      .subscribe();
47	
48	    return () => {
49	      supabase.removeChannel(channel);
50	    };
51	  }, [qc]);
52	
53	  const flagMap = new Map<string, { enabled: boolean; value_json: Record<string, unknown> }>();
54	  flags?.forEach((f) => flagMap.set(f.key, { enabled: f.enabled, value_json: (f.value_json ?? {}) as Record<string, unknown> }));
55	
56	  return { flags: flagMap, isLoading };
57	}
58	
59	/**
60	 * Hook to check a single feature flag by key.
61	 * Returns { enabled, value, isLoading }.
62	 */
63	export function useFeatureFlag(key: string) {
64	  const { flags, isLoading } = useFeatureFlags();
65	  const flag = flags.get(key);
66	  return {
67	    enabled: flag?.enabled ?? false,
68	    value: flag?.value_json ?? {},
69	    isLoading,
70	    ready: !isLoading,
71	  };
72	}
